// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {B} from "../src/B.sol";

contract InvMutTest is Test {
    B c;
    function setUp() public { c = new B(); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0);
        vm.deal(address(this), amount);
        uint256 ownerBefore = c.owner().balance;
        bool ok;
        try c.go{value: amount}() { ok = true; } catch { ok = false; }
        if (ok) {
            assertTrue(c.owner().balance == ownerBefore + amount);
        }
    }
}
